style.css:
@-moz-document domain("youtube.com") {
/* 1. Inyecta tu fondo en la raíz absoluta y en cada capa de YouTube */
    :root,
    html,
    body,
    ytd-app,
    ytd-page-manager,
    #page-manager,
    #content,
    #masthead-container {
        background: url("https://redd.it") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* 2. Destruye los códigos de color internos de YouTube (Variables) convirtiéndolos en transparentes */
    :root, 
    html[dark], 
    [dark],
    html[light],
    [light] {
        --yt-spec-base-background: rgba(0, 0, 0, 0.4) !important;
        --yt-spec-raised-background: rgba(0, 0, 0, 0.5) !important;
        --yt-spec-general-background-a: rgba(0, 0, 0, 0.4) !important;
        --yt-spec-general-background-b: rgba(0, 0, 0, 0.4) !important;
        --yt-spec-menu-background: rgba(20, 20, 20, 0.8) !important;
        --yt-spec-touch-response: rgba(0, 0, 0, 0) !important;
        --yt-main-app-background-blocker: transparent !important;
        --yt-main-app-background: transparent !important;
        --ytd-rich-grid-chips-background: transparent !important;
    }

    /* 3. Vuelve totalmente invisibles los paneles, bloques de video, barras laterales y fondos opacos */
    #columns,
    #contentContainer,
    #masthead,
    #background.ytd-masthead,
    #player-container-outer,
    #inner-header-container,
    #guide-content.ytd-app,
    ytd-watch-flexy,
    ytd-browse,
    ytd-guide-renderer,
    ytd-mini-guide-renderer,
    ytd-rich-grid-renderer,
    ytd-rich-item-renderer,
    ytd-video-renderer,
    ytd-comment-thread-renderer,
    ytd-section-list-renderer,
    ytd-item-section-renderer,
    yt-chip-cloud-renderer {
        background-color: transparent !important;
        background: transparent !important;
    }
}
